package hu.synostream.android;
import java.io.*;import java.util.*;import java.nio.charset.StandardCharsets;import org.junit.Test;import static org.junit.Assert.*;
public class MatroskaAudioTest {
    static byte[] join(byte[]...parts)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();for(byte[] p:parts)b.write(p);return b.toByteArray();}
    static byte[] element(int id,byte[] bytes)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();int count=id>0xffffff?4:id>0xffff?3:id>0xff?2:1;for(int n=count-1;n>=0;n--)b.write(id>>(8*n));if(bytes.length>=127)throw new IllegalArgumentException();b.write(0x80|bytes.length);b.write(bytes);return b.toByteArray();}
    static byte[] track(int number,String language,byte[]...extra)throws Exception{return element(0xae,join(element(0xd7,new byte[]{(byte)number}),element(0x83,new byte[]{2}),element(0x86,"A_AC3".getBytes(StandardCharsets.US_ASCII)),element(0x22b59c,language.getBytes(StandardCharsets.US_ASCII)),join(extra)));}
    static byte[] fixture()throws Exception{return join(new byte[]{0x18,0x53,(byte)0x80,0x67,(byte)0xff},element(0x1654ae6b,join(track(1,"hun"),track(2,"eng"))),new byte[]{1,2,3,4,5});}
    @Test public void realLanguagesAreReadAndChoicePreservesSizeAndMediaBytes()throws Exception{byte[] original=fixture(),copy=original.clone();List<MatroskaAudio.Track> tracks=MatroskaAudio.inspect(original);assertEquals(2,tracks.size());assertEquals("hun",tracks.get(0).language);assertEquals("eng",tracks.get(1).language);Map<Long,Byte> patch=MatroskaAudio.select(tracks,2);assertFalse(patch.isEmpty());MatroskaAudio.patch(copy,copy.length,0,patch);List<MatroskaAudio.Track> selected=MatroskaAudio.inspect(copy);assertTrue(selected.get(0).enabledOffset>=0);assertEquals(0,copy[selected.get(0).enabledOffset]);assertEquals(original.length,copy.length);assertArrayEquals(Arrays.copyOfRange(original,original.length-5,original.length),Arrays.copyOfRange(copy,copy.length-5,copy.length));assertArrayEquals(fixture(),original);}
    @Test public void rangePatchingUsesAbsoluteOffset()throws Exception{byte[] original=fixture(),whole=original.clone();Map<Long,Byte> patch=MatroskaAudio.select(MatroskaAudio.inspect(original),2);MatroskaAudio.patch(whole,whole.length,0,patch);for(int offset=0;offset<original.length;offset+=7){byte[] range=Arrays.copyOfRange(original,offset,Math.min(original.length,offset+7));MatroskaAudio.patch(range,range.length,offset,patch);assertArrayEquals(Arrays.copyOfRange(whole,offset,offset+range.length),range);}}
    @Test public void unknownTrackCannotChangeStream()throws Exception{try{MatroskaAudio.select(MatroskaAudio.inspect(fixture()),999);fail();}catch(IllegalArgumentException expected){}}
    @Test public void tracksChecksumIsRecalculatedAfterSelection()throws Exception{byte[] payload=join(track(1,"hun"),track(2,"eng"));java.util.zip.CRC32 crc=new java.util.zip.CRC32();crc.update(payload);long value=crc.getValue();byte[] checksum={(byte)value,(byte)(value>>8),(byte)(value>>16),(byte)(value>>24)};byte[] header=join(new byte[]{0x18,0x53,(byte)0x80,0x67,(byte)0xff},element(0x1654ae6b,join(element(0xbf,checksum),payload)));Map<Long,Byte> patch=MatroskaAudio.select(MatroskaAudio.inspect(header),2);assertFalse(patch.isEmpty());MatroskaAudio.patch(header,header.length,0,patch);int crcOffset=12,contentOffset=16;crc.reset();crc.update(header,contentOffset,header.length-contentOffset);long actual=0;for(int n=0;n<4;n++)actual|=(long)(header[crcOffset+n]&255)<<(8*n);assertEquals(crc.getValue(),actual);}
    @Test public void segmentWideChecksumIsNotSilentlyInvalidated()throws Exception{byte[] header=join(new byte[]{0x18,0x53,(byte)0x80,0x67,(byte)0xff},element(0xbf,new byte[4]),element(0x1654ae6b,join(track(1,"hun"),track(2,"eng"))));assertTrue(MatroskaAudio.select(MatroskaAudio.inspect(header),2).isEmpty());}
    @Test public void chosenTrackBecomesDefaultEvenIfOriginallyNonDefault()throws Exception{byte[] header=join(new byte[]{0x18,0x53,(byte)0x80,0x67,(byte)0xff},element(0x1654ae6b,join(track(1,"hun",element(0x88,new byte[]{1})),track(2,"eng",element(0x88,new byte[]{0})))));List<MatroskaAudio.Track> tracks=MatroskaAudio.inspect(header);MatroskaAudio.patch(header,header.length,0,MatroskaAudio.select(tracks,2));assertEquals(0,header[tracks.get(0).defaultOffset]);assertEquals(1,header[tracks.get(1).defaultOffset]);}
    @Test public void versionOneUsesDefaultFlagWithoutAddingVersionTwoEnabledFlag()throws Exception{byte[] header=join(element(0x1a45dfa3,element(0x4287,new byte[]{1})),fixture());List<MatroskaAudio.Track> before=MatroskaAudio.inspect(header);MatroskaAudio.patch(header,header.length,0,MatroskaAudio.select(before,2));List<MatroskaAudio.Track> after=MatroskaAudio.inspect(header);assertEquals(-1,after.get(0).enabledOffset);assertTrue(after.get(0).defaultOffset>=0);assertEquals(0,header[after.get(0).defaultOffset]);}
}
